function sameDocumentUrl(expectedUrl: string, currentUrl: string): boolean {
  if (!expectedUrl || !currentUrl) return false;

  try {
    const expected = new URL(expectedUrl);
    const current = new URL(currentUrl);
    return expected.href === current.href;
  } catch {
    return false;
  }
}

function hasChallengeEvidence(html: string): boolean {
  return challengeEnvelopeEvidence.some((pattern) => pattern.test(html));
}

function recordIdentifier(record: ParsedRecord): string | null {
  for (const key of ["id", "identifier", "identifiant"]) {
    const value = record[key];
    if (typeof value === "string" && value.length > 0) return value;
  }
  return null;
}

function decodeHtml(value: string): string {
  return value
    .replace(/&quot;/g, "\"")
    .replace(/&#39;/g, "'")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">");
}

function parserBodies(html: string): string[] {
  const bodies = [html];
  const attribute = /data-json-data\\s*=\\s*([\"'])([\\s\\S]*?)\\1/i.exec(html);
  if (attribute) bodies.push(decodeHtml(attribute[2]));
  const raw = /^\\s*(\\{[\\s\\S]*\\})\\s*(?:<|$)/.exec(html);
  if (raw) bodies.push(raw[1]);
  return bodies;
}

function parseRecords(html: string): ParsedRecord[] {
  for (const body of parserBodies(html)) {
    try {
      const records = xe.parseXe({ body });
      if (records.length > 0) return records.filter(isRecord);
    } catch {
      // Try the next representation of the same document.
    }
  }
  return [];
}

function parseSearch(html: string): boolean {
  return parserBodies(html).some((body) => {
    try {
      xe.parseXeSearch(body);
      return true;
    } catch {
      return false;
    }
  });
}

function hasMatchingDetailRecord(
  html: string,
  expectedUrl: string,
  expectedId: string | undefined,
): boolean {
  const records = parseRecords(html);

  return records.some((value) => {
    if (!isRecord(value) || typeof value.url !== "string") return false;

    const identifier = recordIdentifier(value);
    return identifier !== null &&
      (expectedId === undefined || identifier === expectedId) &&
      sameDocumentUrl(expectedUrl, value.url);
  });
}

